import {cabinet,rect,text,tile,colors} from './cabinet.js';
import {shuffled,swipeDirection} from './shared.js';
export const SHAPES=[[[0,1],[1,1],[2,1],[3,1]],[[1,0],[2,0],[1,1],[2,1]],[[1,0],[0,1],[1,1],[2,1]],[[1,0],[2,0],[0,1],[1,1]],[[0,0],[1,0],[1,1],[2,1]],[[0,0],[0,1],[1,1],[2,1]],[[2,0],[0,1],[1,1],[2,1]]];
export function fitsBlocks(board,cells,x,y){return cells.every(([dx,dy])=>{const xx=x+dx,yy=y+dy;return xx>=0&&xx<10&&yy<16&&(yy<0||board[yy][xx]===0);});}
export function clearBlockLines(board){const kept=board.filter(row=>row.some(v=>v===0)),n=16-kept.length;while(kept.length<16)kept.unshift(Array(10).fill(0));return {board:kept,count:n};}
export function rotateBlock(cells,size=3){return cells.map(([x,y])=>[size-1-y,x]);}
export function createBlocks(mount,api){const q=cabinet(mount,api,{accent:'#88caff'}),c=q.c;let board,bag=[],kind=0,next=0,cells,x=3,y=0,fall=0,lock=0,lines=0,origin=null;
 function take(){if(!bag.length)bag=shuffled([0,1,2,3,4,5,6]);return bag.pop();}
 function spawn(){kind=next;next=take();cells=SHAPES[kind].map(p=>[...p]);x=3;y=0;fall=0;lock=0;if(!fitsBlocks(board,cells,x,y))q.finish('A full house.',`${lines} lines cleared. Give those blocks a little more room.`);}
 function reset(){board=Array.from({length:16},()=>Array(10).fill(0));bag=[];next=take();lines=0;spawn();}
 function settle(){for(const [dx,dy] of cells)if(y+dy>=0)board[y+dy][x+dx]=kind+1;const result=clearBlockLines(board);board=result.board;if(result.count){lines+=result.count;q.add([0,100,300,500,800][result.count]);q.sound('clear',result.count*2);q.say(result.count===4?'FOUR LINES! +800':`${result.count} LINE${result.count>1?'S':''} CLEARED`);q.burst(144,380);}else q.sound('lock');if(lines>=40){q.finish('Forty-line club.',`40 lines in ${Math.ceil(q.elapsed)} seconds.`,true);return;}spawn();}
 function move(dx){if(!q.active)return;if(fitsBlocks(board,cells,x+dx,y)){x+=dx;q.sound('move');}}
 function rotate(){if(!q.active||kind===1)return;const rotated=rotateBlock(cells,kind===0?4:3);for(const kick of [0,-1,1,-2,2])if(fitsBlocks(board,rotated,x+kick,y)){cells=rotated;x+=kick;q.sound('rotate');return;}}
 function drop(){if(!q.active)return;while(fitsBlocks(board,cells,x,y+1))y++;q.burst(24+(x+1)*24,44+(y+1)*24);settle();}
 reset();return {start(){q.start();reset();origin=null;},tap(){rotate();},action:drop,direction(d){if(d==='left')move(-1);if(d==='right')move(1);if(d==='up')rotate();if(d==='down'&&q.active){if(fitsBlocks(board,cells,x,y+1))y++;else settle();}},pointerDown(p){origin=q.local(p);},pointerUp(p){const end=q.local(p),d=swipeDirection(origin,end);origin=null;if(d==='down')drop();if(d==='up')rotate();if(d==='left')move(-1);if(d==='right')move(1);},cancel(){origin=null;},tick(dt){q.frame(dt,dt=>{fall+=dt;const interval=Math.max(.13,.78-Math.floor(lines/4)*.06);if(fall>=interval){fall=0;if(fitsBlocks(board,cells,x,y+1))y++;}if(!fitsBlocks(board,cells,x,y+1)){lock+=dt;if(lock>.38)settle();}else lock=0;},()=>{q.header('CLEAR 40 LINES',`${lines}/40`);rect(c,20,40,248,392,'#101c30',10);for(let r=0;r<16;r++)for(let col=0;col<10;col++){const v=board[r][col];rect(c,24+col*24,44+r*24,22,22,v?colors[(v-1)%6]:'#1e2b3d',4);}let ghost=y;while(fitsBlocks(board,cells,x,ghost+1))ghost++;for(const [dx,dy] of cells){rect(c,24+(x+dx)*24,44+(ghost+dy)*24,22,22,'#d4e7ff30',4);tile(c,24+(x+dx)*24,44+(y+dy)*24,22,22,colors[kind%6]);}text(c,'NEXT',314,60,14,'#b6c7db');for(const [dx,dy] of SHAPES[next])rect(c,279+dx*17,83+dy*17,15,15,colors[next%6],3);text(c,'LEVEL',314,163,14,'#b6c7db');text(c,1+Math.floor(lines/4),314,191,26,'#88caff',750);text(c,'TAP',314,270,14,'#c6d7ea');text(c,'rotate',314,290,14,'#a2b9cf');text(c,'SWIPE ↓',314,335,12,'#c6d7ea');text(c,'drop',314,355,14,'#a2b9cf');q.footer('Swipe sideways to move. Tap to rotate.');});},destroy:q.destroy};}
